import test from 'node:test';
import assert from 'node:assert/strict';
import {save,restore} from './simulation.js';
import {partyDelayCampaign,delayedPartyCampaign,partyRescueRoute} from './party-delay-fixtures.js';
import {decidePartyDelay,partyDelayOpinions,advancePartyDelays} from './party-delay.js';
import {finishSurvivalDay,launchSurvivalSortie,returnSurvivalSortie,survivalDayPreview} from './survival-base.js';
import {dispatchSurvivalParty,resolveSurvivalPartyMissions,moveSurvivalPartyMember} from './survival-parties.js';
import {gridAct,endGridTurn} from './combat-grid.js';
import {survivalPage} from './survival-ui.js';
import {combatMissionInfo} from './combat-missions.js';
const event=s=>s.survivalRun.parties.delays[0];
test('risky real supply dispatch delays original members without paying rewards or removing deployment',()=>{const ready=partyDelayCampaign(),prior=save(ready);let s=delayedPartyCampaign();assert.equal(save(ready),prior);assert.equal(event(s).status,'pending');assert.equal(event(s).members.length,2);assert.equal(s.survivalRun.members.length,6);for(const m of s.survivalRun.members.filter(m=>event(s).members.includes(m.key))){assert.equal(m.deployment,'party-2');assert.equal(m.injury,m.key===event(s).members[0]?1:0);}assert.throws(()=>moveSurvivalPartyMember(s,'member-2','party-1'));const food=s.survivalRun.resources.food;assert.deepEqual(resolveSurvivalPartyMissions(s),[]);assert.equal(s.survivalRun.resources.food,food);});
test('low-risk supply and guard still return normally',()=>{for(const kind of ['supply','guard']){let s=partyDelayCampaign();s.survivalRun.threat=20;s=finishSurvivalDay(dispatchSurvivalParty(s,'party-2',kind));assert.ok(!s.survivalRun.parties.delays?.length);assert.equal(s.survivalRun.parties.reports[0].success,true);assert.equal(s.survivalRun.members[2].deployment,undefined);}});
test('display and preview cannot advance the radio, dehydrate, reroll or mutate saves',()=>{const s=delayedPartyCampaign(),before=save(s);for(let i=0;i<3;i++){assert.match(survivalPage(s),/돌아오지 않은 무전/);assert.match(survivalPage(s,'parties'),/편의점 보급팀/);survivalDayPreview(s);partyDelayOpinions(s,event(s));}assert.equal(save(s),before);assert.deepEqual(restore(before),s);});
test('waiting uses actual nights, drops field water once a night and eventually returns with consequences',()=>{let s=delayedPartyCampaign();s=decidePartyDelay(s,event(s).id,'wait');assert.throws(()=>decidePartyDelay(s,event(s).id,'wait'));const water=s.survivalRun.members[2].hydration;s=finishSurvivalDay(restore(save(s)));assert.equal(event(s).waits,1);assert.equal(s.survivalRun.members[2].hydration,water-15);const saved=save(s);assert.deepEqual(advancePartyDelays(s),[]);assert.equal(save(s),saved);s=finishSurvivalDay(s);assert.equal(event(s).status,'resolved');assert.equal(event(s).method,'fallback');assert.ok(!s.survivalRun.members[2].deployment);assert.equal(s.survivalRun.members[2].injury,2);assert.equal(s.survivalRun.members.length,6);});
test('recall brings actual original party back once, drops supplies and records a specific memory',()=>{let s=delayedPartyCampaign(),food=s.survivalRun.resources.food;s=decidePartyDelay(s,event(s).id,'recall');assert.equal(event(s).method,'recall');assert.equal(s.survivalRun.resources.food,food);assert.equal(s.survivalRun.members[2].partyRescueMemories[0].rescued,false);assert.throws(()=>decidePartyDelay(restore(save(s)),event(s).id,'recall'));assert.equal(s.survivalRun.members[2].injury,2);});
test('live four-turn direct rescue returns existing residents and both parties remember it',()=>{let s=delayedPartyCampaign(),school=structuredClone(s.relations),id=event(s).id;s=launchSurvivalSortie(s,'partyRescue',id);assert.equal(event(s).status,'direct');assert.match(combatMissionInfo(s.combatTrial).title,/연결 통로/);assert.equal(Object.keys(s.combatTrial.actors).length,2);assert.throws(()=>decidePartyDelay(s,id,'recall'));for(const [key,action] of partyRescueRoute)s=key==='end'?endGridTurn(s):gridAct(s,key,action);assert.equal(s.combatTrial.status,'victory');assert.equal(s.combatTrial.protection.held,4);assert.ok(s.combatTrial.enemies.some(e=>e.balance>0));s=returnSurvivalSortie(restore(save(s)));assert.equal(event(s).method,'direct');assert.equal(s.survivalRun.members.length,6);assert.ok(!s.survivalRun.members[2].deployment);assert.equal(s.survivalRun.members[2].partyRescueMemories[0].role,'stranded');assert.equal(s.survivalRun.members[1].partyRescueMemories[0].role,'helper');assert.equal(s.survivalRun.parties.bonds['member:member-2'].trust,3);assert.deepEqual(s.relations,school);assert.match(partyDelayOpinions(s,event(s)).find(o=>o.key==='member-1').line,/지난번/);assert.throws(()=>returnSurvivalSortie(s));});
test('aborted or failed direct rescue leaves request and deployed party intact and allows retry',()=>{for(const fail of [false,true]){let s=delayedPartyCampaign();const id=event(s).id;s=launchSurvivalSortie(s,'partyRescue',id);if(fail){for(let i=0;i<4&&s.combatTrial.status==='active';i++)s=endGridTurn(s);assert.equal(s.combatTrial.status,'failed');s=returnSurvivalSortie(s);}else s=returnSurvivalSortie(s,{abandon:true});assert.equal(event(s).status,'pending');assert.equal(s.survivalRun.members[2].deployment,'party-2');assert.equal(s.survivalRun.members.length,6);assert.ok(!s.survivalRun.members[2].partyRescueMemories);s=decidePartyDelay(s,id,'recall');assert.equal(event(s).status,'resolved');}});
test('backup consumes real rations and an action, saves deployment and resolves once next night',()=>{let s=delayedPartyCampaign(),r=s.survivalRun,food=r.resources.food,water=r.resources.water,actions=r.actions;s=decidePartyDelay(s,event(s).id,'backup','party-3');assert.equal(s.survivalRun.resources.food,food-2);assert.equal(s.survivalRun.resources.water,water-2);assert.equal(s.survivalRun.actions,actions-1);assert.equal(s.survivalRun.members[4].deployment,'party-3');assert.equal(event(s).status,'backup');assert.throws(()=>moveSurvivalPartyMember(s,'member-4','party-1'));s=finishSurvivalDay(restore(save(s)));assert.equal(event(s).method,'backup');assert.equal(s.survivalRun.parties.reports.length,1);assert.equal(s.survivalRun.members[4].partyRescueMemories[0].role,'helper');assert.ok(s.survivalRun.members.every(m=>!m.deployment));assert.deepEqual(resolveSurvivalPartyMissions(s),[]);});
test('backup unavailable/poorly supplied is atomic, dangerous dispatch returns via fallback',()=>{for(const mutate of [s=>s.survivalRun.resources.water=0,s=>s.survivalRun.actions=0,s=>s.survivalRun.members[4].injury=3]){const s=delayedPartyCampaign();mutate(s);const before=save(s);assert.throws(()=>decidePartyDelay(s,event(s).id,'backup','party-3'));assert.equal(save(s),before);}let s=delayedPartyCampaign();s.survivalRun.threat=92;s=decidePartyDelay(s,event(s).id,'backup','party-3');s=finishSurvivalDay(s);assert.equal(event(s).method,'recall');assert.ok(s.survivalRun.members.every(m=>!m.deployment));assert.equal(s.survivalRun.members[4].injury,1);});
test('opinions respond to actual trust, friendship, wounds, supplies, and witnessed rescue memories',()=>{const s=delayedPartyCampaign(),m=s.survivalRun.members[1],e=event(s);assert.equal(partyDelayOpinions(s,e).find(o=>o.key===m.key).choice,'wait');s.survivalRun.parties.bonds['member:'+m.key]={trust:30};assert.equal(partyDelayOpinions(s,e).find(o=>o.key===m.key).choice,'direct');m.injury=1;assert.equal(partyDelayOpinions(s,e).find(o=>o.key===m.key).choice,'recall');m.injury=0;s.survivalRun.resources.food=0;assert.equal(partyDelayOpinions(s,e).find(o=>o.key===m.key).choice,'recall');});
test('forged victory cannot release stranded party and unknown events cannot launch a rescue',()=>{let s=delayedPartyCampaign();assert.throws(()=>launchSurvivalSortie(s,'partyRescue','missing'));s=launchSurvivalSortie(s,'partyRescue',event(s).id);s.combatTrial.status='victory';const before=save(s);assert.throws(()=>returnSurvivalSortie(s),/보호/);assert.equal(save(s),before);});
test('injuries sustained by the protected party during actual battle persist after successful evacuation',()=>{let s=delayedPartyCampaign();s=launchSurvivalSortie(s,'partyRescue',event(s).id);s=endGridTurn(s);const hurt=s.combatTrial.protection.wounds;assert.ok(hurt>0&&hurt<3);for(let i=0;i<3;i++){s=gridAct(s,'taei','guard');s=endGridTurn(s);}assert.equal(s.combatTrial.status,'victory');s=returnSurvivalSortie(s);assert.equal(s.survivalRun.members[2].injury,Math.min(3,1+hurt));assert.equal(event(s).status,'resolved');});
